"""Generate the dependency-free KTC website from its service catalogue."""
from pathlib import Path
from html import escape as e
import json
import os

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'dist'
SERVICES = json.loads((ROOT / 'data/services.json').read_text())
ORIGIN = os.getenv('SITE_URL', 'https://kenya-travel-concierge.upbeatfern7.chatgpt.site').rstrip('/')
GROUPS = {'travel': 'Travel & Arrivals', 'living': 'Life & Relocation', 'support': 'Your Local Presence'}
PHONE = '+254 717 762323'
EMAIL = 'info.kenyatravelconcierge@gmail.com'
WA = 'https://wa.me/254717762323'
ARROW = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
DIAGONAL = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>'
CHECK = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>'

def photo(item, extra='', crop=None):
    x, y, w, h = crop or item['crop']
    return f'<div class="source-photo {extra}" style="--cx:{x};--cy:{y};--cw:{w};--ch:{h}"><img src="/assets/{item["image"]}" alt="{e(item["title"])} — KTC brand imagery" loading="lazy" width="720" height="1600"></div>'

def brand():
    return '<a class="brand" href="/" aria-label="Kenya Travel Concierge home"><span class="logo-window"><img src="/assets/ktc-logo-source.jpeg" width="720" height="1600" alt="KTC crown and laurel logo"></span><span class="brand-name">KENYA TRAVEL<span>CONCIERGE</span></span></a>'

def header(current=''):
    menu = ''.join(f'<a href="/services/{s["slug"]}/">{e(s["title"])}</a>' for s in SERVICES)
    return f'''<a class="skip-link" href="#main">Skip to content</a>
    <header class="site-header"><div class="header-inner">{brand()}
      <nav class="desktop-nav" aria-label="Main navigation">
        <div class="nav-dropdown"><button class="nav-service-trigger" aria-expanded="false" aria-controls="service-menu">Our services <svg viewBox="0 0 12 12" aria-hidden="true"><path d="m3 4.5 3 3 3-3"/></svg></button>
          <div class="mega-menu" id="service-menu" hidden><div class="mega-intro"><span class="eyebrow">Thoughtfully coordinated</span><h3>How can we<br>help you?</h3><a class="text-link" href="/services/">Explore all services {ARROW}</a></div><div class="mega-links">{menu}</div></div>
        </div>
        <a href="/#approach">Our approach</a><a href="/#about">About KTC</a>
      </nav>
      <a class="header-enquire" href="/contact/">Make an enquiry {DIAGONAL}</a>
      <button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button>
    </div><nav id="mobile-menu" class="mobile-menu" aria-label="Mobile navigation" hidden><a href="/services/">Our services</a><a href="/#approach">Our approach</a><a href="/#about">About KTC</a><a href="/contact/">Make an enquiry</a><a href="tel:+254717762323">{PHONE}</a></nav></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="wrap footer-top"><div class="footer-brand">{brand()}<p>Your trusted presence in Kenya.<br>The details, beautifully handled.</p><p class="footer-motto">PRIVATE. LOCAL. RELIABLE.</p></div>
      <div><h3>Explore</h3><a href="/services/">Our services</a><a href="/#approach">Our approach</a><a href="/#about">About KTC</a><a href="/contact/">Get in touch</a></div>
      <div><h3>Let’s talk</h3><a href="tel:+254717762323">{PHONE}</a><a class="footer-email" href="mailto:{EMAIL}">{EMAIL}</a><a href="{WA}" target="_blank" rel="noopener noreferrer">WhatsApp {DIAGONAL}</a><span class="footer-availability">24-hour concierge enquiries</span></div>
      <div><h3>Stay connected</h3><a href="https://www.instagram.com/kenyatravelconcierge/" target="_blank" rel="noopener noreferrer">Instagram {DIAGONAL}</a><p>Based in Kenya.<br>Here for you, wherever you are.</p></div></div>
      <div class="wrap footer-bottom"><span>© 2026 Kenya Travel Concierge. All rights reserved.</span><a href="/privacy/">Privacy & enquiries</a><a href="#top">Back to top ↑</a></div></footer>
      <a class="floating-whatsapp" href="{WA}?text=Hello%20KTC%2C%20I%27d%20like%20to%20make%20an%20enquiry." target="_blank" rel="noopener noreferrer" aria-label="Chat with Kenya Travel Concierge on WhatsApp"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 11.5a8 8 0 0 1-12 7L3 20l1.5-5a8 8 0 1 1 15.5-3.5Z"/><path d="M8 7.5c-1 3 2 6.5 5.5 7.5l2-1.5-2-1.5-1 1c-1.6-.7-2.8-1.9-3.5-3.5l1-1-1.5-2Z"/></svg><span>Let’s talk</span></a>'''

def cta():
    return f'''<section class="closing-cta"><div class="wrap"><span class="eyebrow">A little less to think about</span><h2>Leave the details<br><em>with us.</em></h2><p>A visit. A move. Something that needs a trusted local hand.<br>Tell us what you have in mind.</p><a class="button button-light" href="/contact/">Start a conversation {DIAGONAL}</a></div><span class="cta-monogram" aria-hidden="true">KTC</span></section>'''

def page(title, description, body, path='/', current=''):
    url = ORIGIN + path
    schema = {'@context':'https://schema.org','@type':'Organization','name':'Kenya Travel Concierge','url':ORIGIN,'telephone':'+254717762323','email':EMAIL,'sameAs':['https://www.instagram.com/kenyatravelconcierge/']}
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#123b30"><title>{e(title)} | Kenya Travel Concierge</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)} | Kenya Travel Concierge"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/kenya-savannah.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/app.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body id="top">{header(current)}<main id="main">{body}</main>{footer()}</body></html>'''
    html = html.replace('<br>', '<br> ')
    target=OUT / path.lstrip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html)

def home():
    airport=SERVICES[0]; lifestyle=SERVICES[3]; construction=SERVICES[7]
    worlds=''
    for n,g,item,crop,desc in [(1,'travel',airport,[355,58,360,268],'Arrive well. Move effortlessly. Make the most of your time.'),(2,'living',lifestyle,[322,65,323,241],'From everyday details to a whole new beginning in Kenya.'),(3,'support',construction,[356,58,291,217],'A trusted pair of hands for your property, projects, and priorities.')]:
        worlds+=f'<a class="world-card" href="/services/?category={g}"><div class="world-visual">{photo(item,crop=crop)}<span class="world-number">0{n}</span><span class="world-arrow">{DIAGONAL}</span></div><h3>{GROUPS[g]}</h3><p>{desc}</p><span class="text-link">Explore services {ARROW}</span></a>'
    body=f'''<section class="hero" aria-labelledby="hero-title"><img class="hero-image" src="/assets/kenya-savannah.png" alt="An acacia tree above a sunlit Kenyan savannah — illustrative landscape" fetchpriority="high" width="1942" height="809"><div class="hero-shade"></div><div class="wrap hero-content"><span class="eyebrow">YOUR PEOPLE ON THE GROUND IN KENYA</span><h1 id="hero-title">Kenya, with<br><em>peace of mind.</em></h1><p>From your first welcome to the details back home.<br>Private concierge, thoughtfully tailored to you.</p><div class="hero-actions"><a class="button button-light" href="/services/">Discover our services {DIAGONAL}</a><a class="hero-text-link" href="/contact/">Speak to a concierge {ARROW}</a></div></div><div class="wrap hero-bottom"><span>PRIVATE. LOCAL. RELIABLE.</span><a href="#welcome">A warmer welcome awaits <span>↓</span></a><span>KENYA TRAVEL CONCIERGE</span></div></section>
    <section class="intro-section section" id="welcome"><div class="wrap intro-layout"><div><span class="eyebrow">THE LUXURY OF HAVING IT HANDLED</span><h2>More time to enjoy.<br><em>Less to arrange.</em></h2></div><div class="intro-copy"><p>Whether you’re visiting Kenya, coming home, settling in, or looking after an investment from afar, having someone you trust makes all the difference.</p><p>We are Kenya Travel Concierge: your discreet local link for travel, everyday life, and the things that need a little more attention. One conversation. A service shaped around you.</p><a class="text-link" href="#about">Get to know KTC {ARROW}</a></div></div></section>
    <section class="worlds-section section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">A WORLD OF POSSIBILITIES</span><h2>How can we<br><em>take care of you?</em></h2></div><a class="text-link" href="/services/">View all ten services {ARROW}</a></div><div class="worlds-grid">{worlds}</div></div></section>
    <section class="find-section section" aria-labelledby="find-title"><div class="wrap find-layout"><div><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2 id="find-title">Your plans.<br><em>Your kind of support.</em></h2><p>Start with what brings you here.<br>We’ll help with what comes next.</p></div><div class="finder"><div class="finder-tabs" role="tablist" aria-label="Find services for your plans"><button role="tab" id="tab-visit" aria-selected="true" aria-controls="panel-visit" tabindex="0">I’m visiting</button><button role="tab" id="tab-move" aria-selected="false" aria-controls="panel-move" tabindex="-1">I’m relocating</button><button role="tab" id="tab-away" aria-selected="false" aria-controls="panel-away" tabindex="-1">I’m abroad</button></div>
      <div role="tabpanel" id="panel-visit" aria-labelledby="tab-visit"><span class="finder-label">YOUR VISIT, BEAUTIFULLY COORDINATED</span><h3>Arrive. Unwind.<br>We’ll take it from here.</h3><p>Airport welcomes, a car when you need it, and the reservations and personal touches that make your stay feel effortless.</p><div class="finder-links"><a href="/services/airport-meet-and-greet/">Airport meet & greet {ARROW}</a><a href="/services/car-hire-and-chauffeur/">Car hire & chauffeur {ARROW}</a><a href="/services/vip-and-executive-concierge/">VIP & executive concierge {ARROW}</a></div></div>
      <div role="tabpanel" id="panel-move" aria-labelledby="tab-move" hidden><span class="finder-label">A THOUGHTFUL START IN KENYA</span><h3>A new chapter.<br>A familiar helping hand.</h3><p>Get local guidance, find the right neighbourhood, prepare your home, and bring everyday life together with support around your move.</p><div class="finder-links"><a href="/services/relocation-and-settling-in/">Relocation & settling in {ARROW}</a><a href="/services/consultation-and-planning/">Consultation & planning {ARROW}</a><a href="/services/lifestyle-concierge/">Lifestyle concierge {ARROW}</a></div></div>
      <div role="tabpanel" id="panel-away" aria-labelledby="tab-away" hidden><span class="finder-label">CLOSER TO HOME, WHEREVER YOU ARE</span><h3>Your priorities here.<br>Your peace of mind there.</h3><p>Stay informed about your home, build, or local requests with coordinated checks, photo updates, and a trusted presence on the ground.</p><div class="finder-links"><a href="/services/property-care-and-business-oversight/">Property & business oversight {ARROW}</a><a href="/services/construction-oversight/">Construction oversight {ARROW}</a><a href="/services/errands-and-trusted-representation/">Errands & representation {ARROW}</a><a href="/services/procurement-and-import-coordination/">Procurement & imports {ARROW}</a></div></div></div></div></section>
    <section class="about-section section" id="about"><div class="wrap about-layout"><div class="about-art">{photo(lifestyle,crop=[322,65,323,420])}<div class="about-seal"><span>THOUGHTFUL SERVICE</span><strong>Always<br><em>personal.</em></strong><span>KENYA TRAVEL CONCIERGE</span></div></div><div class="about-copy"><span class="eyebrow">PRIVATE. LOCAL. RELIABLE.</span><h2>A local connection.<br><em>A personal commitment.</em></h2><p>The best kind of support understands what matters to you. At KTC, we bring attentive coordination and a trusted local presence to the parts of life you’d rather leave in capable hands.</p><p>For Kenyans abroad, international guests, expatriates, professionals, and investors, we make the practical feel personal: listening first, agreeing the details, and keeping you informed.</p><div class="brand-values"><div><span>01</span><h3>Discretion, always</h3><p>Your time, priorities, and privacy guide the way we work.</p></div><div><span>02</span><h3>Clarity at every step</h3><p>Agreed arrangements and useful updates, wherever you are.</p></div></div></div></div></section>
    <section class="approach-section section" id="approach"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">THOUGHTFUL FROM THE FIRST CONVERSATION</span><h2>Effortless starts<br><em>with understanding.</em></h2></div><p class="section-aside">No two requests are quite the same.<br>That’s where we begin.</p></div><ol class="process-grid"><li><span>01 / CONNECT</span><h3>Tell us what matters.</h3><p>Share your plans, timing, and preferences. A visit, a move, or simply something you need handled.</p></li><li><span>02 / CONSIDER</span><h3>We shape the details.</h3><p>We confirm the scope, arrangements, and quotation with you before coordination begins.</p></li><li><span>03 / COORDINATE</span><h3>You get on with life.</h3><p>Your local concierge brings things together and keeps you informed along the way.</p></li></ol></div></section>
    {cta()}
    <section class="faq-section section"><div class="wrap faq-layout"><div><span class="eyebrow">A FEW HELPFUL DETAILS</span><h2>Before we<br><em>begin.</em></h2></div><div class="faq-list"><details><summary>Can you help if I’m outside Kenya?<span>+</span></summary><p>Yes. Our services are designed to support Kenyans abroad, international guests, and owners managing interests remotely. Tell us where you need local support and we’ll confirm the arrangements.</p></details><details><summary>Can I combine several services?<span>+</span></summary><p>Absolutely. You can combine airport reception, transport, lifestyle requests, relocation support, or other services into one agreed brief.</p></details><details><summary>How do you price your services?<span>+</span></summary><p>Services are quoted around your request, location, timing, and the coordination required. Contact us with a few details and we will confirm the service scope and applicable third-party costs before proceeding.</p></details><details><summary>What is the easiest way to reach you?<span>+</span></summary><p>Message us on <a href="{WA}" target="_blank" rel="noopener noreferrer">WhatsApp</a>, call <a href="tel:+254717762323">{PHONE}</a>, or email <a href="mailto:{EMAIL}">{EMAIL}</a>. Our enquiry page helps you put your request together.</p></details></div></div></section>'''
    page('Private concierge. A warmer welcome to Kenya.', 'Private concierge, airport meet and greet, chauffeur travel, relocation, property care, and trusted local support across Kenya.', body)

def catalogue():
    cards=''
    for i,s in enumerate(SERVICES):
        cards+=f'<a class="service-card" data-category="{s["group"]}" href="/services/{s["slug"]}/"><span class="service-index">{i+1:02d}</span><div><span class="eyebrow">{GROUPS[s["group"]]}</span><h2>{e(s["title"])}</h2><p>{e(s["summary"])}</p><span class="text-link">Discover this service {ARROW}</span></div><span class="service-card-arrow">{DIAGONAL}</span></a>'
    body=f'''<section class="page-intro wrap"><a class="breadcrumb" href="/">Home /</a><span class="eyebrow">OUR SERVICES</span><h1>Whatever brings you here.<br><em>We’ll handle the details.</em></h1><p>Ten considered services. One trusted local connection.<br>Explore the support that fits your plans.</p></section><section class="catalogue-section"><div class="wrap"><div class="service-filters" role="group" aria-label="Filter services"><button data-filter="all" aria-pressed="true">All services <span>10</span></button><button data-filter="travel" aria-pressed="false">Travel & arrivals <span>3</span></button><button data-filter="living" aria-pressed="false">Life & relocation <span>3</span></button><button data-filter="support" aria-pressed="false">Your local presence <span>4</span></button></div><p class="filter-status sr-only" role="status" aria-live="polite">Showing all 10 services</p><div class="services-grid">{cards}</div><div class="catalogue-note"><p>Something a little different in mind?</p><a class="text-link" href="/contact/">Tell us what you need {ARROW}</a></div></div></section>{cta()}'''
    page('Our Services', 'Explore all ten KTC services: travel, arrivals, relocation, lifestyle concierge, property care, construction monitoring, errands, and procurement.', body, '/services/')

def detail(s):
    includes=''.join(f'<li>{CHECK}<span>{e(x)}</span></li>' for x in s['includes'])
    related=''.join(f'<a href="/services/{x["slug"]}/">{e(x["title"])} {ARROW}</a>' for x in SERVICES if x['group']==s['group'] and x['slug']!=s['slug'])
    body=f'''<section class="service-detail-intro wrap"><div><a class="breadcrumb" href="/services/">Our services / {GROUPS[s['group']]}</a><span class="eyebrow">{GROUPS[s['group']]}</span><h1>{e(s['title'])}</h1><p class="detail-strapline">{e(s['eyebrow'])}</p><p>{e(s['description'])}</p><a class="button button-green" href="/contact/?service={s['slug']}">Enquire about this service {DIAGONAL}</a></div><div class="detail-art">{photo(s)}<span class="detail-art-caption">THE KTC COLLECTION / {GROUPS[s['group']].upper()}</span></div></section><section class="detail-includes section"><div class="wrap detail-layout"><div><span class="eyebrow">THOUGHTFULLY COORDINATED</span><h2>The details<br><em>we take care of.</em></h2><p>Each request is tailored to your plans.<br>We agree the scope and quotation with you.</p></div><div><ul class="includes-list">{includes}</ul><p class="service-note">{e(s['note'])}</p></div></div></section><section class="related-section section"><div class="wrap"><span class="eyebrow">A LITTLE MORE SUPPORT</span><h2>You may also<br><em>be looking for.</em></h2><div class="related-links">{related}</div><a class="text-link" href="/services/">Explore all services {ARROW}</a></div></section>{cta()}'''
    page(s['title'], s['summary'], body, f'/services/{s["slug"]}/')

def contact():
    opts=''.join(f'<option value="{s["slug"]}">{e(s["title"])}</option>' for s in SERVICES)
    body=f'''<section class="contact-section wrap"><div class="contact-copy"><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h1>Let’s make it<br><em>feel effortless.</em></h1><p>A few details are all we need to begin.<br>Tell us what you have in mind, and we’ll take it from there.</p><div class="contact-methods"><a href="tel:+254717762323"><span>CALL US</span><strong>{PHONE}</strong>{DIAGONAL}</a><a href="{WA}" target="_blank" rel="noopener noreferrer"><span>MESSAGE US</span><strong>Chat on WhatsApp</strong>{DIAGONAL}</a><a href="mailto:{EMAIL}"><span>EMAIL US</span><strong class="contact-email">{EMAIL}</strong>{DIAGONAL}</a></div><p class="contact-availability">Private. Local. Reliable.<br><span>24-hour concierge enquiries · Support across Kenya</span></p></div>
      <div class="enquiry-panel"><span class="eyebrow">MAKE AN ENQUIRY</span><h2>A service shaped<br><em>around you.</em></h2><form id="enquiry-form"><div class="form-grid"><div class="field"><label for="name">Your name <span>*</span></label><input id="name" name="name" autocomplete="name" placeholder="Full name" required maxlength="100"></div><div class="field"><label for="email">Email address <span>*</span></label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="200"></div><div class="field"><label for="phone">Phone number <span class="optional">(optional)</span></label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="Include country code" maxlength="40"></div><div class="field"><label for="service">How can we help? <span>*</span></label><select id="service" name="service" required><option value="">Select a service</option>{opts}<option value="multiple">Several services / a bespoke request</option></select></div><div class="field field-full"><label for="timing">When do you need support? <span class="optional">(optional)</span></label><input id="timing" name="timing" placeholder="Your dates, or tell us if you’re flexible" maxlength="160"></div><div class="field field-full"><label for="message">Tell us a little more <span>*</span></label><textarea id="message" name="message" rows="4" placeholder="Your plans, location, and the details that matter to you…" required maxlength="3000"></textarea></div></div><button class="button button-green form-submit" type="submit">Continue on WhatsApp {DIAGONAL}</button><button class="email-enquiry" type="submit" name="channel" value="email">Prefer email? Prepare an email enquiry {ARROW}</button><p class="form-explanation">Your enquiry opens in WhatsApp or your email app for you to review and send. Please share only the details needed to plan your service. <a href="/privacy/">Privacy & enquiries</a></p><div id="enquiry-result" class="enquiry-result" role="status" aria-live="polite" hidden></div></form></div></section>'''
    page('Contact Your Concierge', 'Speak to Kenya Travel Concierge. Call +254 717 762323, message on WhatsApp, or prepare a personalised enquiry.', body, '/contact/')

def privacy():
    body=f'''<section class="text-page wrap"><span class="eyebrow">PRIVACY & ENQUIRIES</span><h1>A little clarity.<br><em>Before you connect.</em></h1><div class="prose"><h2>Making an enquiry</h2><p>The website enquiry form prepares a message on your device. It does not submit your details to a KTC website database. You choose whether to send your prepared message through WhatsApp or your email application.</p><h2>The details you share</h2><p>We ask for your name, email, preferred service, and a short description so we can understand your request. Your phone number and timing are optional. Please do not include passport numbers, payment card details, passwords, or other sensitive documents in an initial enquiry.</p><h2>External services</h2><p>Links to WhatsApp and Instagram open services operated by their respective providers, which apply their own privacy practices. The website uses no advertising pixels, marketing cookies, or enquiry analytics scripts. Hosting services may process technical information needed to serve the website.</p><h2>Following up with KTC</h2><p>When you send a message, KTC uses the information you provide to discuss and coordinate your requested services. Any further documents, third-party arrangements, or authorisations should be agreed directly with your concierge.</p><h2>Contact</h2><p>For questions about an enquiry or the information you have shared, contact <a href="mailto:{EMAIL}">{EMAIL}</a> or call <a href="tel:+254717762323">{PHONE}</a>.</p><a class="text-link" href="/contact/">Back to your enquiry {ARROW}</a></div></section>'''
    page('Privacy & Enquiries', 'How the KTC website enquiry form works, the information you choose to share, and how to contact your concierge.', body, '/privacy/')

if __name__ == '__main__':
    home(); catalogue(); contact(); privacy()
    for s in SERVICES: detail(s)
    page('Page Not Found', 'Find your way back to Kenya Travel Concierge.', '<section class="page-intro wrap"><span class="eyebrow">A SMALL DETOUR</span><h1>Let’s get you<br><em>back on your way.</em></h1><p>The page you are looking for could not be found.</p><a class="button button-green" href="/">Back to KTC '+ARROW+'</a></section>', '/404/')
    (OUT/'404.html').write_text((OUT/'404/index.html').read_text())
    paths=['/','/services/','/contact/','/privacy/']+[f'/services/{s["slug"]}/' for s in SERVICES]
    (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc></url>' for p in paths)+'</urlset>')
    (OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {ORIGIN}/sitemap.xml\n')
    print(f'Built {len(paths)} pages, a 404 page, and sitemap into {OUT}')
